'use client'

import * as React from 'react'
import { cn } from "@/lib/utils"
import { ChevronLeftIcon, ChevronRightIcon, MoreHorizontalIcon } from 'lucide-react'

import { Button, buttonVariants } from './button'

function Pagination({ className, ...props }: React.ComponentProps<'nav'>) {
  return (
    <nav
      role="navigation"
      aria-label="pagination"
      data-slot="pagination"
      className={cn('mx-auto flex w-full justify-center', className)}
      {...props}
    />
  )
}

function PaginationContent({ className, ...props }: React.ComponentProps<'ul'>) {
  return (
    <ul
      data-slot="pagination-content"
      className={cn('flex flex-row items-center gap-1', className)}
      {...props}
    />
  )
}

function PaginationItem({ ...props }: React.ComponentProps<'li'>) {
  return <li data-slot="pagination-item" {...props} />
}

type PaginationLinkProps = {
  isActive?: boolean
  isDisabled?: boolean
} & Pick<React.ComponentProps<typeof Button>, 'size'> &
  React.ComponentProps<'a'>

function PaginationLink({ className, isActive, size = 'icon', ...props }: PaginationLinkProps) {
  return (
    <a
      aria-current={isActive ? 'page' : undefined}
      data-slot="pagination-link"
      data-active={isActive}
      className={cn(
        buttonVariants({
          variant: isActive ? 'outline' : 'ghost',
          size,
        }),
        className
      )}
      {...props}
    />
  )
}

function PaginationPrevious({ className, ...props }: React.ComponentProps<typeof PaginationLink>) {
  return (
    <PaginationLink
      aria-label="Go to previous page"
      size="default"
      className={cn('gap-1 px-2.5 sm:pe-4', className)}
      {...props}
    >
      <ChevronLeftIcon size={16} />
      <span>Previous</span>
    </PaginationLink>
  )
}

function PaginationNext({ className, ...props }: React.ComponentProps<typeof PaginationLink>) {
  return (
    <PaginationLink
      aria-label="Go to next page"
      size="default"
      className={cn('gap-1 px-2.5 sm:ps-4', className)}
      {...props}
    >
      <span>Next</span>
      <ChevronRightIcon size={16} />
    </PaginationLink>
  )
}

function PaginationEllipsis({ className, ...props }: React.ComponentProps<'span'>) {
  return (
    <span
      aria-hidden
      data-slot="pagination-ellipsis"
      className={cn('flex size-9 items-center justify-center', className)}
      {...props}
    >
      <MoreHorizontalIcon size={16} />
      <span className="sr-only">More pages</span>
    </span>
  )
}

export {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
}

import type { InjectionKey, ComputedRef } from "vue";
import type { PaginationApi } from "@/lib/utils";

export type PaginationContextValue = {
  api: ComputedRef<PaginationApi | null>;
};

export const PaginationContextKey = Symbol("PaginationContext") as InjectionKey<PaginationContextValue>;

import { normalizeProps, useMachine } from '@zag-js/vue'
import { paginationConnect, paginationMachine } from "@/lib/utils"
import { computed } from 'vue'

export type UsePaginationProps = {
    id?: string
    page?: number
    defaultPage?: number
    pageSize?: number
    defaultPageSize?: number
    count?: number
    siblingCount?: number
    boundaryCount?: number
}

type PaginationChangeDetails = {
    page: number
    pageSize: number
}

type UsePaginationEmit = {
    (event: 'update:page', page: number): void
    (event: 'change', details: PaginationChangeDetails): void
    (event: 'update:pageSize', pageSize: number): void
}

export function usePagination(props: UsePaginationProps, emit: UsePaginationEmit) {
    const service = useMachine(paginationMachine as never, {
        id: props.id,
        page: props.page,
        defaultPage: props.defaultPage,
        pageSize: props.pageSize,
        defaultPageSize: props.defaultPageSize,
        count: props.count,
        siblingCount: props.siblingCount,
        boundaryCount: props.boundaryCount,
        onPageChange(details: PaginationChangeDetails) {
            emit('update:page', details.page)
            emit('change', { page: details.page, pageSize: details.pageSize })
        },
        onPageSizeChange(details: PaginationChangeDetails) {
            emit('update:pageSize', details.pageSize)
        },
    } as never)

    return computed(() => paginationConnect(service as never, normalizeProps))
}

